import { describe, expect, it } from 'vitest';
import {
  MAX_BUTINA, butina, butinaFromBitmap, butinaFromLists, popcount32, tanimotoCpu, topK,
} from './simsearch';
import { butinaFitsGpu, planSimSearchGpu } from './simsearchGpu';

const WORDS = 64;
const empty = () => new Uint32Array(WORDS);

/** Build one packed fingerprint from a list of set bit positions. */
function bits(...set: number[]): Uint32Array {
  const w = empty();
  for (const b of set) w[b >> 5] |= 1 << (b & 31);
  return w;
}

/** RDKit Morgan r=2, 2048 bits, packed little-endian inside each u32 word. */
const MORGAN: [string, string][] = [
  ['Aspirin', ''],
  ['Ibuprofen', ''],
  ['Paracetamol', ''],
  ['Caffeine', ''],
  ['Naproxen', ''],
  ['Diclofenac', ''],
  ['Celecoxib', ''],
  ['Metformin', ''],
  ['Atorvastatin', ''],
  ['Sildenafil', ''],
];

function fromHex(hex: string): Uint32Array {
  const w = new Uint32Array(WORDS);
  for (let i = 0; i < WORDS; i++) w[i] = parseInt(hex.slice(i * 8, i * 8 + 8), 16);
  return w;
}

// Python RDKit: AllChem.GetMorganFingerprintAsBitVect(m, 2, 2048) then
// DataStructs.TanimotoSimilarity for every pair (10 molecules, 45 pairs).
const PAIRS = [0.1951219512195122, 0.2222222222222222, 0.08888888888888889, 0.20454545454545456, 0.1956521739130435, 0.0847457627118644, 0.05128205128205128, 0.15714285714285714, 0.1038961038961039, 0.18421052631578946, 0.08695652173913043, 0.42105263157894735, 0.16666666666666666, 0.08333333333333333, 0.05, 0.15492957746478872, 0.075, 0.0975609756097561, 0.16666666666666666, 0.1590909090909091, 0.09090909090909091, 0.05714285714285714, 0.16666666666666666, 0.06578947368421052, 0.08, 0.07692307692307693, 0.1206896551724138, 0.024390243902439025, 0.07894736842105263, 0.14666666666666667, 0.1320754716981132, 0.09523809523809523, 0.045454545454545456, 0.13157894736842105, 0.0975609756097561, 0.05970149253731343, 0.02127659574468085, 0.15789473684210525, 0.06976744186046512, 0.03636363636363636, 0.10227272727272728, 0.16091954022988506, 0.04225352112676056, 0.012987012987012988, 0.07272727272727272];

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe('popcount and Tanimoto', () => {
  it('counts bits, including the sign bit', () => {
    expect(popcount32(0)).toBe(0);
    expect(popcount32(0xffffffff)).toBe(32);
    expect(popcount32(0x80000001)).toBe(2);
  });

  it('matches hand bit sets', () => {
    const db = new Uint32Array(WORDS * 4);
    db.set(bits(1, 2, 3), 0);
    db.set(bits(2, 3, 4), WORDS);
    db.set(bits(1, 2, 3), WORDS * 2);
    db.set(bits(4, 5, 6), WORDS * 3);
    expect(tanimotoCpu(db, 0, db, 1)).toBe(0.5);
    expect(tanimotoCpu(db, 0, db, 2)).toBe(1);
    expect(tanimotoCpu(db, 0, db, 3)).toBe(0);

    const emptyDb = new Uint32Array(WORDS * 2);
    expect(tanimotoCpu(emptyDb, 0, emptyDb, 1)).toBe(0);
  });

  it('ranks a query with a known answer', () => {
    const q = bits(1, 2, 3);
    const db = new Uint32Array(WORDS * 4);
    db.set(bits(2, 3, 4), 0);      // 2/4 = 0.5
    db.set(bits(1, 2, 3), WORDS);  // 1
    db.set(bits(4, 5), WORDS * 2); // 0
    db.set(bits(1), WORDS * 3);    // 1/3
    const best = topK(q, db, 3);
    expect(best.map((x) => x.index)).toEqual([1, 0, 3]);
    expect(best[0].sim).toBe(1);
    expect(best[1].sim).toBe(0.5);
    expect(best[2].sim).toBeCloseTo(1 / 3, 12);
  });

  it('agrees with Python RDKit Morgan fingerprints on all 45 pairs', () => {
    const fps = MORGAN.map(([, hex]) => fromHex(hex));
    let p = 0;
    for (let i = 0; i < fps.length; i++) {
      for (let j = i + 1; j < fps.length; j++) {
        const got = tanimotoCpu(fps[i], 0, fps[j], 0);
        const expected = PAIRS[p++];
        expect(Math.abs(got - expected), `${MORGAN[i][0]} vs ${MORGAN[j][0]}`).toBeLessThan(1e-9);
      }
    }
    expect(p).toBe(45);
  });
});

describe('Butina clustering', () => {
  it('makes 13 clusters from 3 planted groups of 20 plus 10 singletons', () => {
    const rnd = mulberry32(20261026);
    const n = 70;
    const db = new Uint32Array(n * WORDS);
    const bases = [0, 20, 40];
    for (const base of bases) {
      const fp = empty();
      for (let b = 0; b < 2048; b++) if (rnd() < 0.1) fp[b >> 5] |= 1 << (b & 31);
      db.set(fp, base * WORDS);
      for (let k = 1; k < 20; k++) {
        const copy = fp.slice();
        for (let b = 0; b < 2048; b++) if (rnd() < 0.02) copy[b >> 5] ^= 1 << (b & 31);
        db.set(copy, (base + k) * WORDS);
      }
    }
    for (let k = 0; k < 10; k++) {
      const fp = empty();
      for (let b = 0; b < 2048; b++) if (rnd() < 0.1) fp[b >> 5] |= 1 << (b & 31);
      db.set(fp, (60 + k) * WORDS);
    }

    const res = butina(db, n, 0.4);
    expect(res.centroids.length).toBe(13);
    expect(res.sizes.reduce((a, b) => a + b, 0)).toBe(n);
    for (let k = 0; k < res.centroids.length; k++) expect(res.cluster[res.centroids[k]]).toBe(k);
    expect(res.cluster[0]).toBe(res.cluster[1]);
    expect(res.cluster[0]).toBe(res.cluster[19]);
    expect(res.cluster[20]).toBe(res.cluster[39]);
    expect(res.cluster[40]).toBe(res.cluster[59]);
    for (let i = 60; i < 70; i++) {
      expect(res.sizes[res.cluster[i]]).toBe(1);
      expect(res.centroids[res.cluster[i]]).toBe(i);
    }
    expect(res.sizes.slice(0, 3)).toEqual([20, 20, 20]);
    expect(res.centroids.slice(0, 3)).toEqual([0, 20, 40]);
  });

  it('refuses more than the documented maximum', () => {
    const db = new Uint32Array(WORDS);
    expect(() => butina(db, MAX_BUTINA + 1, 0.4)).toThrow(/limited to 20,000 molecules/);
  });

  it('decodes a GPU bitmap into the same clusters as the CPU path', () => {
    const rnd = mulberry32(7);
    const n = 24;
    const db = new Uint32Array(n * WORDS);
    for (let i = 0; i < n; i++) {
      const fp = empty();
      // Rows 0..7 share a dense core; the rest are progressively sparse.
      for (let b = 0; b < 2048; b++) if (rnd() < (i < 8 ? 0.5 : 0.02)) fp[b >> 5] |= 1 << (b & 31);
      db.set(fp, i * WORDS);
    }
    const cpu = butina(db, n, 0.4);
    const words = Math.ceil(n / 32);
    const bitmap = new Uint32Array(n * words);
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      if (i !== j && 1 - tanimotoCpu(db, i, db, j) <= 0.4) bitmap[i * words + (j >> 5)] |= 1 << (j & 31);
    }
    const gpu = butinaFromBitmap(bitmap, n);
    expect(Array.from(gpu.cluster)).toEqual(Array.from(cpu.cluster));
    expect(gpu.centroids).toEqual(cpu.centroids);
    expect(gpu.sizes).toEqual(cpu.sizes);
    const lists = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => j).filter((j) => j !== i && 1 - tanimotoCpu(db, i, db, j) <= 0.4));
    expect(butinaFromLists(lists, n).sizes).toEqual(cpu.sizes);
  });
});

describe('GPU planning from real limits', () => {
  it('plans the default limits', () => {
    const plan = planSimSearchGpu(5000, {});
    expect(plan.fits).toBe(true);
    expect(plan.perBatch).toBe(5000);
    expect(plan.batches).toBe(1);
    expect(plan.bytesPerBatch).toBeLessThanOrEqual(128 * 1024 * 1024);
    expect(butinaFitsGpu(20_000, {})).toBe(true);
  });

  it('splits to fit a 1 MiB mock limit', () => {
    const cap = 1024 * 1024;
    const plan = planSimSearchGpu(5000, { maxStorageBufferBindingSize: cap, maxBufferSize: cap });
    expect(plan.fits).toBe(true);
    expect(plan.perBatch).toBe(4017);
    expect(plan.batches).toBe(2);
    expect(plan.bytesPerBatch).toBe(1_044_420);
    expect(plan.bytesPerBatch).toBeLessThanOrEqual(cap);
    expect(plan.perBatch * (plan.batches - 1)).toBeLessThan(5000);
    expect(butinaFitsGpu(20_000, { maxStorageBufferBindingSize: cap, maxBufferSize: cap })).toBe(false);
  });
});
